function mostPointsInView(points: number[][], fov: number, at: number[]): number {
  const EPS = 1e-9;
  let here = 0;
  const ang: number[] = [];
  for (const [x, y] of points) {
    const dx = x - at[0], dy = y - at[1];
    if (dx === 0 && dy === 0) { here++; continue; }
    let a = Math.atan2(dy, dx) * 180 / Math.PI;
    if (a < 0) a += 360;
    ang.push(a);
  }
  let best = 0;
  for (const s of ang) {
    let c = 0;
    for (const a of ang) {
      let d = a - s;
      if (d < -EPS) d += 360;
      if (d <= fov + EPS) c++;
    }
    best = Math.max(best, c);
  }
  return best + here;
}

