function mostPointsInView(points: number[][], fov: number, at: number[]): number {
  const EPS = 1e-9;
  let here = 0;
  const ang: number[] = [];
  for (const [x, y] of points) {
    const dx = x - at[0], dy = y - at[1];
    if (dx === 0 && dy === 0) { here++; continue; }
    let a = Math.atan2(dy, dx) * 180 / Math.PI;
    if (a < 0) a += 360;
    ang.push(a);
  }
  ang.sort((p, q) => p - q);
  const m = ang.length;
  for (let i = 0; i < m; i++) ang.push(ang[i] + 360);
  let best = 0, lo = 0;
  for (let hi = 0; hi < ang.length; hi++) {
    while (ang[hi] - ang[lo] > fov + EPS) lo++;
    best = Math.max(best, hi - lo + 1);
  }
  return Math.min(best, m) + here;
}

